import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Your first Grid","description":"Create a Grid, add entries, and configure fields with the right column type.","frontmatter":{"title":"Your first Grid","description":"Create a Grid, add entries, and configure fields with the right column type."},"headers":[],"relativePath":"en/grids/grid-anlegen.md","filePath":"en/grids/grid-anlegen.md","lastUpdated":1787319236000}'),n={name:"en/grids/grid-anlegen.md"};function s(l,e,o,d,h,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="your-first-grid" tabindex="-1">Your first Grid <a class="header-anchor" href="#your-first-grid" aria-label="Permalink to &quot;Your first Grid&quot;">​</a></h1><p>A <strong>Grid</strong> is a table of structured data. It&#39;s the starting point for everything else: forms write into a Grid, views display a Grid, flows react to changes in a Grid.</p><h2 id="create-a-grid" tabindex="-1">Create a Grid <a class="header-anchor" href="#create-a-grid" aria-label="Permalink to &quot;Create a Grid&quot;">​</a></h2><ol><li>Open the Space where the Grid should live.</li><li>In the sidebar, under <strong>Grids</strong>, select <strong>Add Grid</strong>.</li><li>Give it a name.</li></ol><p>ApptiveGrid automatically creates a first view. You never work directly &quot;in the Grid&quot; — you always work in a view of it. See <a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a>.</p><div class="tip custom-block"><p class="custom-block-title">Renaming later is fine</p><p>Grids can be renamed anytime through the context menu. Links, forms, and flows keep working because they don&#39;t reference the Grid by name internally.</p></div><h2 id="create-entries" tabindex="-1">Create entries <a class="header-anchor" href="#create-entries" aria-label="Permalink to &quot;Create entries&quot;">​</a></h2><p>An <strong>entry</strong> is a row. There are three ways to create one:</p><table tabindex="0"><thead><tr><th>Way</th><th>When it makes sense</th></tr></thead><tbody><tr><td>Directly in the table</td><td>While building and for quick fixes</td></tr><tr><td>Via the detail view</td><td>When many fields need filling in</td></tr><tr><td>Via a <a href="/en/formulare/formular-erstellen">Form</a></td><td>When other people are supplying the data</td></tr><tr><td>Via a <a href="/en/flows/aktionen">Flow</a></td><td>When entries should be created automatically</td></tr></tbody></table><p>Clicking a row opens the entry in the detail view with all fields listed one below the other.</p><div class="warning custom-block"><p class="custom-block-title">Entry limit per Grid</p><p>The number of entries per Grid depends on your plan. As you approach the limit, ApptiveGrid shows a notice.</p></div><h2 id="create-fields" tabindex="-1">Create fields <a class="header-anchor" href="#create-fields" aria-label="Permalink to &quot;Create fields&quot;">​</a></h2><p>A <strong>field</strong> is a column. Every field has a <strong>column type</strong>, which determines:</p><ul><li>which values are allowed,</li><li>how the value is displayed,</li><li>which filter conditions are available,</li><li>whether and how it can be requested in forms.</li></ul><p>To create a field:</p><ol><li>Click <strong>+</strong> at the right end of the column headers.</li><li>Give it a <strong>column name</strong>.</li><li>Choose the <strong>column type</strong>.</li><li>Configure the type if it has settings (such as select options or a currency).</li></ol><h3 id="choosing-the-right-column-type" tabindex="-1">Choosing the right column type <a class="header-anchor" href="#choosing-the-right-column-type" aria-label="Permalink to &quot;Choosing the right column type&quot;">​</a></h3><p>The type is the most important decision when creating a field. A rough guide:</p><table tabindex="0"><thead><tr><th>You want to capture …</th><th>Column type</th></tr></thead><tbody><tr><td>Short text, names, subject</td><td><strong>Text</strong></td></tr><tr><td>Longer, formatted text</td><td><strong>Rich Text</strong></td></tr><tr><td>Whole number (quantity, count)</td><td><strong>Number</strong></td></tr><tr><td>Number with decimal places</td><td><strong>Decimal</strong></td></tr><tr><td>Amount of money</td><td><strong>Currency</strong></td></tr><tr><td>Date without time</td><td><strong>Date</strong></td></tr><tr><td>Date with time</td><td><strong>Date and time</strong></td></tr><tr><td>Yes/No</td><td><strong>Checkmark</strong></td></tr><tr><td>One option from a fixed list</td><td><strong>Single Select</strong></td></tr><tr><td>Multiple options from a list</td><td><strong>Multiple Select</strong></td></tr><tr><td>Reference to an entry in another Grid</td><td><strong>Link record</strong></td></tr><tr><td>References to multiple entries</td><td><strong>Link multiple records</strong></td></tr><tr><td>Files and images</td><td><strong>Files</strong></td></tr><tr><td>Postal address</td><td><strong>Address</strong></td></tr><tr><td>Geo coordinates</td><td><strong>Geolocation</strong></td></tr><tr><td>Email address</td><td><strong>E-Mail</strong></td></tr><tr><td>Phone number</td><td><strong>Phone Number</strong></td></tr><tr><td>Web address</td><td><strong>Weblink</strong></td></tr><tr><td>Signature</td><td><strong>Signature</strong></td></tr></tbody></table><p>The complete list with all settings is in the <a href="/en/referenz/spaltentypen">column type reference</a>.</p><h3 id="automatically-filled-fields" tabindex="-1">Automatically filled fields <a class="header-anchor" href="#automatically-filled-fields" aria-label="Permalink to &quot;Automatically filled fields&quot;">​</a></h3><p>ApptiveGrid fills three types itself — you can&#39;t edit them:</p><ul><li><strong>Created at</strong> — when the entry was created</li><li><strong>Created by</strong> — who created the entry</li><li><strong>User</strong> — a reference to a person</li></ul><div class="tip custom-block"><p class="custom-block-title">&quot;Created by&quot; doesn&#39;t only show people</p><p>If an entry was created via a form, this shows <em>Form link</em>. If it came in through the API, it shows <em>API Credentials</em>. That helps answer where a record actually came from.</p></div><h3 id="calculated-fields" tabindex="-1">Calculated fields <a class="header-anchor" href="#calculated-fields" aria-label="Permalink to &quot;Calculated fields&quot;">​</a></h3><p>Three types calculate their value from other data and are also read-only:</p><ul><li><strong>Use linked value</strong> — pulls a value from a linked entry</li><li><strong>Calculate sum</strong> — sums values across multiple linked entries</li><li><strong>Formula</strong> — calculates a value from an expression</li></ul><p>These types require an existing link. Details under <a href="/en/grids/berechnete-felder">Calculated Fields</a>.</p><h2 id="change-a-field" tabindex="-1">Change a field <a class="header-anchor" href="#change-a-field" aria-label="Permalink to &quot;Change a field&quot;">​</a></h2><p>Use the menu in the column header to change name, type, and description.</p><div class="danger custom-block"><p class="custom-block-title">Changing the type can lose data</p><p>If you change a field&#39;s type, ApptiveGrid tries to carry over the existing values. If a value doesn&#39;t fit the new type, it&#39;s lost. For populated columns, take a <a href="/en/grids/csv-export">CSV export</a> as a backup first.</p></div><p>Two error messages come up regularly here:</p><p><strong>&quot;Change not possible. This field is used in a filter.&quot;</strong> A filter in a view references this field. Remove the filter, then change the field.</p><p><strong>&quot;The name already exists&quot;</strong> Field names must be unique within a Grid.</p><h2 id="delete-a-field" tabindex="-1">Delete a field <a class="header-anchor" href="#delete-a-field" aria-label="Permalink to &quot;Delete a field&quot;">​</a></h2><p>Deleting requires confirmation, because the column and its content disappear from all entries. Check beforehand whether forms, views, filters, or flows use this field.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/grids/verknuepfungen">Link Grids</a> — spread data across multiple Grids</li><li><a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a> — display data in different ways</li><li><a href="/en/formulare/formular-erstellen">Create a Form</a> — let others submit data</li><li><a href="/en/referenz/spaltentypen">Column type reference</a> — all types in detail</li></ul>',38)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
